$('#prevCar').onclick=()=>{selectedPlayer=(selectedPlayer+9)%10;buildSetup()};$('#nextCar').onclick=()=>{selectedPlayer=(selectedPlayer+1)%10;buildSetup()};
function makeRoute(track){const samples=catmull(track.points,15);let total=0;for(let i=0;i<samples.length;i++){const a=samples[i],b=samples[(i+1)%samples.length];a.dist=total;total+=Math.hypot(b.x-a.x,b.y-a.y)}samples.forEach(p=>p.fraction=p.dist/total);return {samples,length:total}}
function routeAt(route,f){const d=((f%1)+1)%1*route.length;let lo=0,hi=route.samples.length-1;while(lo<hi){const mid=(lo+hi+1)>>1;if(route.samples[mid].dist<=d)lo=mid;else hi=mid-1}const a=route.samples[lo],b=route.samples[(lo+1)%route.samples.length],seg=Math.hypot(b.x-a.x,b.y-a.y)||1,t=(d-a.dist)/seg;return {x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,angle:Math.atan2(b.y-a.y,b.x-a.x)}}
function closestRoute(route,x,y){let best=Infinity,idx=0;for(let i=0;i<route.samples.length;i++){const p=route.samples[i],d=(p.x-x)**2+(p.y-y)**2;if(d<best){best=d;idx=i}}return {sample:route.samples[idx],fraction:route.samples[idx].fraction,distance:Math.sqrt(best)}}
function drawCircuit(c,route,thumbnail=false){const pts=route.samples;c.lineJoin='round';c.lineCap='round';c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.closePath();c.strokeStyle='#d9dfd0';c.lineWidth=142;c.stroke();c.strokeStyle='#383f3d';c.lineWidth=132;c.stroke();c.strokeStyle='#454c49';c.lineWidth=2;c.stroke();c.strokeStyle='#b9bdb4';c.lineWidth=1.5;c.setLineDash([12,12]);c.stroke();c.setLineDash([]);
// Alternating kerbs along the track's outer edge.
for(let i=0;i<pts.length;i+=5){const p=pts[i],n=pts[(i+1)%pts.length],ang=Math.atan2(n.y-p.y,n.x-p.x);c.save();c.translate(p.x,p.y);c.rotate(ang);c.fillStyle=(i%10===0)?'#e94b42':'#f1f0e5';c.fillRect(-7,-72,14,9);c.fillRect(-7,63,14,9);c.restore()}
const start=pts[0],next=pts[2],a=Math.atan2(next.y-start.y,next.x-start.x);c.save();c.translate(start.x,start.y);c.rotate(a);for(let y=-64;y<65;y+=12){c.fillStyle=(Math.floor((y+64)/12)%2)?'#171a18':'#f8f8ee';c.fillRect(-5,y,10,12)}c.restore();
}
function startRace(){cancelAnimationFrame(raf);const canvas=$('#gameCanvas'),ctx=canvas.getContext('2d'),track=tracks[selectedTrack],route=makeRoute(track);const player=selectedPlayer;let cars=drivers.map((d,i)=>{const slot=(i===player)?0:((i<player)?i:i-1);const prog=(i===player)?0:.012+slot*.013;const pos=routeAt(route,prog);return {id:i,color:d.color,name:d.name,model:d.model,x:pos.x,y:pos.y,angle:pos.angle,speed:0,progress:prog,frac:prog%1,completed:0,rate:.0205+(i%4)*.00065,finished:false,finishTime:0}});const start=routeAt(route,0);cars[player].x=start.x;cars[player].y=start.y;cars[player].angle=start.angle;cars[player].speed=0;
 game={canvas,ctx,route,cars,player,track,startedAt:performance.now(),lastLapAt:performance.now(),bestLap:null,lapTimes:[],lastFrac:0,paused:false,count:3,goAt:performance.now()+800,done:false,acc:0};$('#setup').classList.remove('active');$('#race').classList.add('active');$('#raceTrackTitle').textContent=track.name;$('#countdown').textContent='3';$('#resultOverlay').classList.remove('show');$('#pausedOverlay').classList.remove('show');$('#pauseRace').textContent='Ⅱ  PAUSAR';$('#lapHud').textContent='1 / 5';$('#lapProgress').style.width='0%';$('#timeHud').textContent='00:00';$('#bestHud').textContent='--:--';$('#positionHud').innerHTML='10<small>/10</small>';$('#speedHud').textContent='000';updateLeaderboard();lastFrame=performance.now();raf=requestAnimationFrame(loop)}
function updateLeaderboard(){if(!game)return;const sorted=[...game.cars].sort((a,b)=>b.progress-a.progress);$('#leaderboard').innerHTML=sorted.slice(0,5).map((car,i)=>`<div class="leader-line ${car.id===game.player?'active':''}"><span class="place">${i+1}</span><i class="mini-dot" style="background:${car.color}"></i><span>${car.name}</span></div>`).join('')}
function formatTime(ms){const s=Math.max(0,ms)/1000;return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`}
function loop(now){if(!game)return;const dt=Math.min(.04,(now-lastFrame)/1000);lastFrame=now;const g=game;if(!g.paused&&!g.done){if(now<g.goAt){const rem=Math.ceil((g.goAt-now)/1000);$('#countdown').textContent=rem>0?rem:'GO!'}else{$('#countdown').textContent='';simulate(dt,now)} }drawGame();if(!g.paused&&!g.done){$('#timeHud').textContent=formatTime(now-g.startedAt);const pc=g.cars[g.player];const lap=Math.min(5,pc.completed+1);$('#lapHud').textContent=`${lap} / 5`;$('#lapProgress').style.width=`${Math.max(0,pc.frac*100)}%`;$('#positionHud').innerHTML=`${[...g.cars].sort((a,b)=>b.progress-a.progress).findIndex(c=>c.id===g.player)+1}<small>/10</small>`;$('#speedHud').textContent=String(Math.round(pc.speed*2.7)).padStart(3,'0');$('#gearHud').textContent=`MARCHA ${Math.max(1,Math.min(6,Math.floor(pc.speed/17)+1))}`;if(g.bestLap)$('#bestHud').textContent=formatTime(g.bestLap);g.acc+=dt;if(g.acc>.3){updateLeaderboard();g.acc=0}}raf=requestAnimationFrame(loop)}

