function loop(now){if(!game)return;const dt=Math.min(.04,(now-lastFrame)/1000);lastFrame=now;const g=game;if(!g.paused&&!g.done){if(now<g.goAt){const rem=Math.ceil((g.goAt-now)/1000);$('#countdown').textContent=rem>0?rem:'GO!'}else{$('#countdown').textContent='';simulate(dt,now)} }drawGame();if(!g.paused&&!g.done){$('#timeHud').textContent=formatTime(now-g.startedAt);const pc=g.cars[g.player];const lap=Math.min(5,pc.completed+1);$('#lapHud').textContent=`${lap} / 5`;$('#lapProgress').style.width=`${Math.max(0,pc.frac*100)}%`;$('#positionHud').innerHTML=`${[...g.cars].sort((a,b)=>b.progress-a.progress).findIndex(c=>c.id===g.player)+1}<small>/10</small>`;$('#speedHud').textContent=String(Math.round(pc.speed*2.7)).padStart(3,'0');$('#gearHud').textContent=`MARCHA ${Math.max(1,Math.min(6,Math.floor(pc.speed/17)+1))}`;if(g.bestLap)$('#bestHud').textContent=formatTime(g.bestLap);g.acc+=dt;if(g.acc>.3){updateLeaderboard();g.acc=0}}raf=requestAnimationFrame(loop)}
function simulate(dt,now){const g=game,p=g.cars[g.player],route=g.route;for(const car of g.cars){if(car.id!==g.player){if(!car.finished){car.progress+=car.rate*dt;if(car.progress>=5){car.progress=5;car.finished=true;car.finishTime=now-g.startedAt}const pos=routeAt(route,car.progress);car.x=pos.x;car.y=pos.y;car.angle=pos.angle;car.speed=car.rate*route.length}continue}
const steer=(keys.ArrowLeft||keys.a||touch.left?-1:0)+(keys.ArrowRight||keys.d||touch.right?1:0);const gas=keys.ArrowUp||keys.w||touch.gas,brake=keys.ArrowDown||keys.s||touch.brake;const near=closestRoute(route,p.x,p.y);const road=near.distance<60;const accel=gas?66:0;const braking=brake?95:0;p.speed+=accel*dt;p.speed-=braking*dt;p.speed-= (gas?2.5:15)*dt;if(!road)p.speed-=34*dt;p.speed=Math.max(0,Math.min(105,p.speed));const steerPower=(.55+Math.min(p.speed/55,1.25))*(p.speed<5?.35:1);p.angle+=steer*steerPower*dt*(p.speed<12?-1:1);p.x+=Math.cos(p.angle)*p.speed*dt;p.y+=Math.sin(p.angle)*p.speed*dt;
