 function finishRace(){if(game.done)return;game.done=true;const sorted=[...game.cars].sort((a,b)=>b.progress-a.progress),place=sorted.findIndex(c=>c.id===game.player)+1;$('#resultTitle').textContent=place===1?'VITÓRIA!':place<=3?'PÓDIO!':'CORRIDA CONCLUÍDA';$('#resultText').textContent=`Você terminou em ${place}º lugar${game.bestLap?` · melhor volta ${formatTime(game.bestLap)}`:''}. Mais uma volta?`;$('#resultOverlay').classList.add('show')}
